import React from 'react';

function CartPage({ cart, onClearCart }) {
    const handlePlaceOrder = async () => {
        const token = localStorage.getItem('token'); // Retrieve token from storage

        // Initialize orderData
        const orderData = {
            products: cart.map((item) => ({
                product: item.id, // Match the backend's product ID field
                quantity: item.quantity,
                price: item.price,
            })),
            totalAmount: cart.reduce((sum, item) => sum + item.price * item.quantity, 0),
        };

        try {
            const API_URL = 'http://localhost:5000'; // Ensure this matches your backend server's URL

            const response = await fetch(`${API_URL}/api/orders`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`, // Include token for authentication
                },
                body: JSON.stringify(orderData), // Correctly reference orderData
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.message || 'Failed to place order.');
            }

            const placedOrder = await response.json(); // Parse the order data
            alert('Order placed successfully!');
            onClearCart(); // Clear the cart after placing the order
        } catch (err) {
            console.error('Error placing order:', err.message);
            alert(err.message);
        }
    };

    return (
        <div>
            <h1>Your Cart</h1>
            {cart.length === 0 ? (
                <p>Your cart is empty.</p>
            ) : (
                <>
                    <ul>
                        {cart.map((item) => (
                            <li key={item.id}>
                                {item.name} - ${item.price} (x{item.quantity})
                            </li>
                        ))}
                    </ul>
                    <h2>Total: ${cart.reduce((sum, item) => sum + item.price * item.quantity, 0).toFixed(2)}</h2>
                    <button onClick={handlePlaceOrder}>Place Order</button>
                </>
            )}
        </div>
    );
}

export default CartPage;
